from ti_system import *from ti_draw import *from random import *disp_clr()print("+ and - keys to adjust speed")print("Arrow keys to move")print("Y= to increase difficulty")print("window to decrease difficulty")print("zoom to redraw map")print("")print("Reach the right side")print("")print("Press any key to start")sleep(2)wait_key()disp_clr()x=0y=0score=0ex=randint(0,319)ey=randint(0,209)m=5exa=[]eya=[]ewa=[]eha=[]good=Falsesquares=60left=squaresexa=[]eya=[]ewa=[]eha=[]def walls():  global good  set_color(255,0,0)  while left>=0:    while not good:      global left      ew=randint(10,25)      eh=randint(10,25)                  ex=randint(0, 319 - ew)      ey=randint(0, 209 - eh)            no_overlap = ((ex + ew <= x) or (ex >= x + 5) or (ey + eh <= y) or (ey >= y + 5))            if no_overlap:        exa.append(ex)        eya.append(ey)        ewa.append(ew)        eha.append(eh)        left=left-1        good=True    fill_rect(ex,ey,ew,eh)    good=Falsewalls()set_color(0, 0, 0)fill_rect(x, y, 5, 5)while True:  k=get_key(1)  set_color(255, 255, 255)  fill_rect(x, y, 5, 5)  if k==25:    y=y-m  if k==26:    x=x+m  if k==34:    y=y+m  if k==24:    x=x-m  if k==75 and m>1:    m=m-1  if k==85:    m=m+1  if k==11 and squares<150:    squares=squares+10    clear()    eya.clear()    exa.clear()    eha.clear()    ewa.clear()    walls()  if k==13:    clear()    eya.clear()    exa.clear()    eha.clear()    ewa.clear()    walls()  if k==12:    squares=squares-10    clear()    eya.clear()    exa.clear()    eha.clear()    ewa.clear()    walls()  left=squares  for i in range(len(exa)):    if exa[i] + ewa[i] > x:      if exa[i] < x + 5:        if eya[i] + eha[i] > y:          if eya[i] < y + 5:            eya.clear()            exa.clear()            ewa.clear()            eha.clear()            x=0            y=0            disp_clr()            print("")            print("")            print("")            print("Score: " + str(score))            print("")            print("")            print("")            print("Press any key to restart")            sleep(1)            wait_key()            disp_clr()            score=0            clear()            walls()            break  if x>314:    clear()    y=0    x=0    eya.clear()    exa.clear()    eha.clear()    ewa.clear()    score=score+1    walls()    set_color(0, 0, 0)    fill_rect(x, y, 5, 5)  if y>205:    y=205  if y<-1:    y=-1  if x<-1:    x=-1  set_color(0, 0, 0)  fill_rect(x, y, 5, 5)